import React, { useEffect, useState } from "react";

function ProductList({ api }) {
  const [products, setProducts] = useState([]);

  const loadProducts = async () => {
    const response = await api.get("/produtos");
    setProducts(response.data);
  };

  useEffect(() => {
    loadProducts();
  }, []); // Este useEffect roda apenas quando o componente monta (ou a 'key' muda)

  // Função para calcular os custos e lucros
  const calcularValores = (p) => {
    const precoCompraUSD = p.preco_compra;
    const precoVendaBRL = p.preco_venda;
    const iof = p.iof_percent / 100;
    const freteUSD = p.frete_usd; // Já vem calculado do backend
    const taxaDolar = p.taxa_dolar;

    // 1. Custo total em Dólar (USD)
    const custoCompraIOF_USD = precoCompraUSD * (1 + iof);
    const custoTotalUSD = custoCompraIOF_USD + freteUSD;

    // 2. Custo total em Reais (BRL)
    const custoTotalBRL = custoTotalUSD * taxaDolar;

    // 3. Lucro em Reais (BRL)
    const lucroBRL = precoVendaBRL - custoTotalBRL;

    // 4. Lucro Percentual
    const lucroPercent = custoTotalBRL > 0 ? (lucroBRL / custoTotalBRL) * 100 : 0;

    return {
      custoTotalBRL: custoTotalBRL.toFixed(2),
      lucroBRL: lucroBRL.toFixed(2),
      lucroPercent: lucroPercent.toFixed(2),
    };
  };

  return (
    <div>
      <h2>Lista de Produtos</h2>
      <table>
        <thead>
          <tr>
            <th>Nome</th>
            <th>Compra (USD)</th>
            <th>Frete (USD)</th>
            <th>Venda (BRL)</th>
            <th>Custo Total (BRL)</th>
            <th>Lucro (BRL)</th>
            <th>Lucro (%)</th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => {
            const valores = calcularValores(p);
            return (
              <tr key={p.id}>
                <td>{p.nome}</td>
                <td>${p.preco_compra.toFixed(2)}</td>
                <td>${p.frete_usd.toFixed(2)}</td>
                <td>R$ {p.preco_venda.toFixed(2)}</td>
                <td>R$ {valores.custoTotalBRL}</td>
                <td>R$ {valores.lucroBRL}</td>
                <td>{valores.lucroPercent}%</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default ProductList;
